<script setup lang="ts">import { MapPin, RadioTower } from 'lucide-vue-next'; import type { Station } from '~/types/api'; useSeoMeta({title:'Estaciones'}); const {request}=useApi(); const {data:stations,pending,error,refresh}=await useAsyncData('public-stations',()=>request<Station[]>('/public/stations'))</script>
<template><div class="page"><div class="container"><h1 class="page-title">Estaciones meteorológicas</h1><p class="page-subtitle">Estado, fuente y última sincronización de las estaciones disponibles.</p><ErrorState v-if="error" @retry="refresh"/><LoadingState v-else-if="pending"/><div v-else class="grid grid-3 station-grid"><article v-for="s in stations" :key="s.id" class="card"><div class="card-body"><div class="row-between"><span class="station-icon"><RadioTower/></span><span class="badge" :class="s.active?'badge-success':'badge-warning'">{{s.active?'Activa':'Inactiva'}}</span></div><h2>{{s.name}}</h2><p><MapPin/>{{[s.locality,s.department].filter(Boolean).join(', ')||'Ubicación pendiente'}}</p><hr class="divider"><div class="small muted">Fuente: {{s.source_type}}</div><div class="small muted">Código: {{s.code}}</div><div class="small muted">Última sincronización: {{s.last_synced_at?new Date(s.last_synced_at).toLocaleString('es-PY'):'Nunca'}}</div></div></article></div></div></div></template>
